#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

# Snowflake prod + Terraform bootstrap + local-dev dbt (ticket #4). Re-runnable: values already
# in .env are offered as defaults, and finished one-time steps are detected and skipped.
# Background for every step: infra/README.md.

cd "$(dirname "${BASH_SOURCE[0]}")/.."   # repo root, so .env and infra/tf.sh resolve
TOTAL_STAGES=16
KEY_DIR="$HOME/.snowflake/keys"
STATE_BUCKET="serpentair-terraform-state"
TF=infra/tf.sh

# copy_sql SQL: print it and put it on the clipboard for pasting into a Snowsight worksheet.
copy_sql() {
  printf '\n%s\n\n' "$1" | sed 's/^/      /'
  if command -v clip.exe >/dev/null 2>&1; then printf '%s' "$1" | clip.exe && note "(copied to your clipboard)"
  elif command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy && note "(copied to your clipboard)"
  fi
}
# pub_body FILE: the public key without BEGIN/END lines, on one line (what Snowflake wants).
pub_body() { grep -v -- '-----' "$1" | tr -d '\r\n'; }
# pub_fp FILE: the fingerprint Snowflake shows as RSA_PUBLIC_KEY_FP (after "SHA256:").
pub_fp() { openssl rsa -pubin -in "$1" -outform DER 2>/dev/null | openssl dgst -sha256 -binary | openssl enc -base64; }
# run CMD...: show a command, then run it; on failure, offer to keep going or stop.
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  if ! "$@"; then
    warn "that command failed (see the output above)."
    confirm "Continue anyway?" || { warn "stopped. Fix the problem and re-run; finished steps are skipped or harmless to repeat."; exit 1; }
  fi
}

banner "Snowflake prod with cost safeguards (#4)"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Sign up for Snowflake"
say "The 30-day trial starts now. Three choices on the form matter and can't be changed later:"
open_url "https://signup.snowflake.com/"
step "Edition: ${BOLD}Standard${RESET} (about \$2/credit vs \$3 for Enterprise; nothing here needs Enterprise)."
step "Cloud provider: ${BOLD}Amazon Web Services${RESET}."
step "Region: ${BOLD}US East (Ohio)${RESET}, the AWS project's only Region, so S3 → Snowpipe stays in one Region."
step "Activate from the email, choose a username and password, set up MFA when asked."
pause "Press Enter once you're logged in to Snowsight."

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Account identifiers"
say "Terraform and dbt find your account by organization name + account name."
step "In Snowsight, open a new SQL worksheet (Projects → Workspaces, or Worksheets) and run:"
copy_sql "SELECT CURRENT_ORGANIZATION_NAME() AS org, CURRENT_ACCOUNT_NAME() AS account, CURRENT_USER() AS user_name;"
ask SNOWFLAKE_ORGANIZATION_NAME "Paste ORG:"
ask SNOWFLAKE_ACCOUNT_NAME "Paste ACCOUNT:"
ask SNOWFLAKE_ADMIN_USER "Paste USER_NAME (exactly as shown):"
write_env SNOWFLAKE_ORGANIZATION_NAME "$SNOWFLAKE_ORGANIZATION_NAME"
write_env SNOWFLAKE_ACCOUNT_NAME "$SNOWFLAKE_ACCOUNT_NAME"
write_env SNOWFLAKE_ADMIN_USER "$SNOWFLAKE_ADMIN_USER"

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Verify your email in Snowflake"
say "The resource monitor emails you at 50/75/90% of the monthly credit quota, but Snowflake"
say "only emails verified addresses (and the apply may fail if yours isn't verified)."
step "Snowsight: click your name (bottom left) → Settings → My profile → Email → Verify (or Resend)."
step "Click the link in the email Snowflake sends."
pause "Press Enter once the email shows as verified."

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Key pairs"
say "Key-pair auth is how automation logs in to Snowflake: no password, no MFA prompt."
say "Two pairs, each a private key (stays on this machine) + a public key (given to Snowflake):"
note "  admin.p8             your own user: Terraform bootstrap, local dbt, dbt platform dev"
note "  svc_terraform_ci.p8  the CI service user: Terraform prod (here now, GitHub Actions in #9)"
mkdir -p "$KEY_DIR"; chmod 700 "$KEY_DIR" 2>/dev/null || true
for name in admin svc_terraform_ci; do
  if [[ -f "$KEY_DIR/$name.p8" ]]; then
    note "  $name.p8 already exists: keeping it."
  else
    openssl genrsa 2048 2>/dev/null | openssl pkcs8 -topk8 -nocrypt -out "$KEY_DIR/$name.p8"
    chmod 600 "$KEY_DIR/$name.p8" 2>/dev/null || true
    printf '  %s✓ made%s %s\n' "$GREEN" "$RESET" "$KEY_DIR/$name.p8"
  fi
  openssl rsa -in "$KEY_DIR/$name.p8" -pubout -out "$KEY_DIR/$name.pub" 2>/dev/null
done
mkdir -p infra/bootstrap/keys
cp "$KEY_DIR/svc_terraform_ci.pub" infra/bootstrap/keys/svc_terraform_ci.pub
SKIPPED+=("commit infra/bootstrap/keys/svc_terraform_ci.pub (bootstrap reads it on every plan, incl. CI)")
printf '  %s✓ copied%s the CI public key to infra/bootstrap/keys/ (public keys are safe to commit)\n' "$GREEN" "$RESET"
# shellcheck disable=SC2088  # literal ~ on purpose: .env stores it, tf.sh expands it
write_env SNOWFLAKE_ADMIN_PRIVATE_KEY_PATH "~/.snowflake/keys/admin.p8"
write_env SNOWFLAKE_CI_USER "SVC_TERRAFORM_CI"
# shellcheck disable=SC2088  # literal ~ on purpose: .env stores it, tf.sh expands it
write_env SNOWFLAKE_CI_PRIVATE_KEY_PATH "~/.snowflake/keys/svc_terraform_ci.p8"
warn "Back up $KEY_DIR somewhere safe (e.g. a password manager). Lose a key and you rotate it."
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Give your user the admin public key"
say "The one grant Terraform can't make for itself: it needs a way in first."
step "Run this in a Snowsight worksheet:"
admin_sql="USE ROLE ACCOUNTADMIN;
ALTER USER \"$SNOWFLAKE_ADMIN_USER\" SET RSA_PUBLIC_KEY = '$(pub_body "$KEY_DIR/admin.pub")';
DESC USER \"$SNOWFLAKE_ADMIN_USER\" ->> SELECT \"value\" FROM \$1 WHERE \"property\" = 'RSA_PUBLIC_KEY_FP';"
copy_sql "$admin_sql"
say "The last query should return:  ${BOLD}SHA256:$(pub_fp "$KEY_DIR/admin.pub")${RESET}"
pause "Press Enter once it matches."

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Sign in to AWS"
say "Terraform keeps its state in S3, so it needs your AWS session (profile serpentair)."
if aws sts get-caller-identity --profile serpentair >/dev/null 2>&1; then
  printf '  %s✓ already signed in%s\n' "$GREEN" "$RESET"
else
  run aws login --profile serpentair
fi
pause

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Bootstrap: apply on local state"
say "infra/bootstrap creates the S3 state bucket and the Snowflake CI user (SVC_TERRAFORM_CI)."
say "Its state can't go in the bucket yet (the bucket doesn't exist), so this first apply keeps"
say "state locally, via a temporary, git-ignored backend_override.tf."
# Done = bootstrap's state already lives in S3. (Not "the bucket exists": a first apply can
# create the bucket and then fail on the Snowflake side; a re-run must resume from local state.)
BOOTSTRAPPED=0
if aws s3api head-object --bucket "$STATE_BUCKET" --key bootstrap/terraform.tfstate --profile serpentair >/dev/null 2>&1; then
  BOOTSTRAPPED=1
  printf '  %s✓ bootstrap state is already in S3: applied before, skipping.%s\n' "$GREEN" "$RESET"
  note "To change bootstrap later: infra/tf.sh bootstrap plan / apply."
else
  [[ -f infra/bootstrap/terraform.tfstate ]] && note "Found local state from an earlier attempt: resuming from it."
  printf 'terraform {\n  backend "local" {}\n}\n' > infra/bootstrap/backend_override.tf
  run "$TF" bootstrap init -input=false -reconfigure
  say "Terraform shows its plan: expect 7 AWS resources (bucket and its settings) and 4 Snowflake"
  say "ones (the CI user and its three role grants). Type ${BOLD}yes${RESET} to apply."
  run "$TF" bootstrap apply
fi
pause

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Bootstrap: move its state into S3"
if (( BOOTSTRAPPED )); then
  printf '  %s✓ already done%s\n' "$GREEN" "$RESET"
else
  say "The bucket exists now, so remove the override and let Terraform copy the state into it."
  rm -f infra/bootstrap/backend_override.tf
  run "$TF" bootstrap init -migrate-state -force-copy -input=false
  say "Checking Terraform reads the state from S3:"
  if "$TF" bootstrap state list; then
    rm -f infra/bootstrap/terraform.tfstate infra/bootstrap/terraform.tfstate.backup
    printf '  %s✓ state is in s3://%s/bootstrap/; local copy removed%s\n' "$GREEN" "$STATE_BUCKET" "$RESET"
  else
    warn "couldn't read state from S3; left infra/bootstrap/terraform.tfstate in place. Ask for help before retrying."
    exit 1
  fi
fi
pause

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Prod: apply"
say "infra/envs/prod runs as SVC_TERRAFORM_CI, the identity CI will use, so this also proves"
say "that user's permissions. It creates the resource monitor, PROD_WH and DEV_WH, SERPENTAIR_PROD"
say "(RAW, ANALYTICS), SERPENTAIR_DEV, and the roles. Type ${BOLD}yes${RESET} to apply."
run "$TF" prod init -input=false
run "$TF" prod apply
pause

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "Prod: plan is clean"
say "If the code and Snowflake agree, a plan right after apply changes nothing."
rc=0; "$TF" prod plan -detailed-exitcode -input=false || rc=$?
case $rc in
  0) printf '  %s✓ No changes: prod matches the code.%s\n' "$GREEN" "$RESET" ;;
  2) warn "the plan still wants changes (drift). Note what it shows and tell Claude."; SKIPPED+=("prod plan not clean") ;;
  *) warn "plan failed; see above."; SKIPPED+=("prod plan failed") ;;
esac
pause

# ── 11 ─────────────────────────────────────────────────────────────────────
stage "Remove warehouses no monitor covers"
say "New accounts come with COMPUTE_WH (and sometimes others). Terraform doesn't manage them and"
say "no resource monitor guards them, so they could spend past the ceiling. Run:"
copy_sql "USE ROLE ACCOUNTADMIN;
SHOW WAREHOUSES ->> SELECT \"name\", \"size\", \"resource_monitor\" FROM \$1;"
pause "Press Enter for the drop statement."
say "Drop every warehouse except PROD_WH and DEV_WH, e.g.:"
copy_sql "DROP WAREHOUSE IF EXISTS COMPUTE_WH;"
note "PROD_WH and DEV_WH should show SERPENTAIR_MONTHLY. Use DEV_WH (role DEVELOPER) for worksheets."
pause "Press Enter once only PROD_WH and DEV_WH remain."

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "Install dbt (v2 / Fusion) and the VS Code extension"
find_dbt() {
  local c
  for c in "$(command -v dbt 2>/dev/null || true)" "$HOME/.local/bin/dbt.exe" "$HOME/.local/bin/dbt"; do
    [[ -n "$c" && -x "$c" ]] && "$c" --version 2>/dev/null | grep -qi fusion && { printf '%s' "$c"; return 0; }
  done
  return 1
}
DBT_BIN="$(find_dbt || true)"
if [[ -n "$DBT_BIN" ]]; then
  printf '  %s✓ dbt Fusion already installed:%s %s\n' "$GREEN" "$RESET" "$("$DBT_BIN" --version 2>/dev/null | head -1)"
else
  say "dbt Labs' official installer puts the Fusion CLI in ~/.local/bin."
  if confirm "Run the installer now?"; then
    if command -v powershell.exe >/dev/null 2>&1; then
      run powershell.exe -NoProfile -ExecutionPolicy Bypass -Command "irm https://public.cdn.getdbt.com/fs/install/install.ps1 | iex"
    else
      run sh -c "curl -fsSL https://public.cdn.getdbt.com/fs/install/install.sh | sh -s -- --update"
    fi
    DBT_BIN="$(find_dbt || true)"
  fi
fi
if command -v code >/dev/null 2>&1; then
  run code --install-extension dbtLabsInc.dbt
else
  step "In VS Code: Extensions → search 'dbt' → install the one published by dbt Labs."
fi
pause

# ── 13 ─────────────────────────────────────────────────────────────────────
stage "Local-dev dbt profile"
say "dbt reads connection settings from ~/.dbt/profiles.yml (outside the repo)."
say "You build into your own schema in SERPENTAIR_DEV and read the prod gold record."
ask DBT_DEV_SCHEMA "Your personal schema (e.g. dbt_dpickering):"
write_env DBT_DEV_SCHEMA "$DBT_DEV_SCHEMA"
key_win="$(cygpath -m "$KEY_DIR/admin.p8" 2>/dev/null || echo "$KEY_DIR/admin.p8")"
profile_block="serpentair:
  target: dev
  outputs:
    dev:
      type: snowflake
      account: ${SNOWFLAKE_ORGANIZATION_NAME}-${SNOWFLAKE_ACCOUNT_NAME}
      user: ${SNOWFLAKE_ADMIN_USER}
      private_key_path: ${key_win}
      role: DEVELOPER
      warehouse: DEV_WH
      database: SERPENTAIR_DEV
      schema: ${DBT_DEV_SCHEMA}
      threads: 4"
mkdir -p "$HOME/.dbt"
if [[ -f "$HOME/.dbt/profiles.yml" ]] && grep -q '^serpentair:' "$HOME/.dbt/profiles.yml"; then
  # shellcheck disable=SC2088  # message text, not a path
  warn "~/.dbt/profiles.yml already has a 'serpentair' profile; leaving it alone. It should read:"
  printf '%s\n' "$profile_block" | sed 's/^/      /'
else
  printf '%s\n' "$profile_block" >> "$HOME/.dbt/profiles.yml"
  printf '  %s✓ wrote%s the serpentair profile to ~/.dbt/profiles.yml\n' "$GREEN" "$RESET"
fi
pause

# ── 14 ─────────────────────────────────────────────────────────────────────
stage "dbt: connect and build"
if [[ -z "${DBT_BIN:-}" ]]; then
  warn "dbt Fusion not found; open a new terminal and run, from transform/: dbt debug, then dbt build"
  SKIPPED+=("dbt debug + dbt build in transform/")
else
  say "dbt debug checks the connection; dbt build creates the connection_check view in"
  say "SERPENTAIR_DEV.${DBT_DEV_SCHEMA}."
  pushd transform >/dev/null
  run "$DBT_BIN" debug
  run "$DBT_BIN" build
  popd >/dev/null
fi
pause

# ── 15 ─────────────────────────────────────────────────────────────────────
stage "dbt platform: connect Snowflake"
say "Carried over from #3: connect the dbt platform project to this Snowflake account."
note "Menu names follow dbt's docs; if a label differs slightly, pick the nearest match."
open_url "$(_existing DBT_ACCESS_URL || echo https://cloud.getdbt.com)"
step "Account settings → Connections → New connection → Snowflake:"
note "    Account: ${SNOWFLAKE_ORGANIZATION_NAME}-${SNOWFLAKE_ACCOUNT_NAME}   Database: SERPENTAIR_DEV   Warehouse: DEV_WH   Role: DEVELOPER"
step "Account settings → Projects → Portfolio-2026-Nov → Connection: choose the new connection."
step "Your profile → Credentials → Portfolio-2026-Nov → auth method ${BOLD}Key pair${RESET}:"
note "    Username: ${SNOWFLAKE_ADMIN_USER}   Private key: contents of $KEY_DIR/admin.p8   Schema: ${DBT_DEV_SCHEMA}"
step "Open Studio (the IDE) and run 'dbt build': connection_check should build there too."
pause

# ── 16 ─────────────────────────────────────────────────────────────────────
stage "dbt platform: free-plan checks"
say "The account is on a 14-day Starter trial (until ~2026-11-28), so what you can click now may"
say "be more than the free Developer plan allows. Look for 'upgrade'/'Starter' badges."
say "Just look: don't create anything you'd have to undo."
step "Orchestration → Environments → Create environment: which deployment types are offered"
step "(Production, Staging, General)? Does the dbt version list offer 'Latest' (Fusion)?"
ask DBT_CHECK_ENVS "What did you see for environments and versions?"
step "Orchestration → Jobs → Create job: is there a 'Merge job' option (and a badge on it)?"
